#!/usr/bin/env python3
"""Reproducible browser/static audit for MB-W01-L1. Loads inline when sandbox forbids file/http navigation."""
import json,re,hashlib,pathlib,sys,xml.etree.ElementTree as ET
import fitz
from playwright.sync_api import sync_playwright
ROOT=pathlib.Path(__file__).resolve().parents[1]; WEB=ROOT/'books/MB-W01-L1'
SRC=json.loads((WEB/'content.json').read_text()); M=json.loads((WEB/'web-manifest.json').read_text());PDF=ROOT/'materials/MB-W01-L1/book.pdf'
RESULTS={}; DETAILS={};ERRORS=[]
def check(key,ok,detail=None):RESULTS[key]=bool(ok);DETAILS[key]=detail;print(('PASS' if ok else 'FAIL'),key,detail if detail is not None else '')
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
check('PDF exists, exact 121 A4 pages',PDF.exists() and len(fitz.open(PDF))==121 and all(abs(p.rect.width-595.28)<1 and abs(p.rect.height-841.89)<1 for p in fitz.open(PDF)))
check('PDF hash matches web manifest',sha(PDF)==M['book_pdf_sha256'])
check('Canonical JSON matches manifest',sha(WEB/'content.json')==M['book_content_sha256'])
check('HTML hash matches manifest',sha(WEB/'index.html')==M['web_revision'])
check('Lesson identity',SRC['lesson_id']==1 and SRC['week']==1 and SRC['slot']==1 and SRC['module']==1 and SRC['title']==M['title'])
check('Counts: theory, examples, practice', (len(SRC['theory']),len(SRC['examples']),len(SRC['practice']))==(13,30,90))
check('Practice levels 30/30/20/10',[sum(p['level']==l for p in SRC['practice']) for l in 'ABCD']==[30,30,20,10])
check('Practice IDs unique',len({p['id'] for p in SRC['practice']})==90)
check('Example IDs unique',len({e['id'] for e in SRC['examples']})==30)
check('Every practice has 2 hints, solution, answer',all(len(p['hints'])==2 and p['solution'].strip() and p['answer'].strip() for p in SRC['practice']))
check('All 59 reflection answers present',sum(map(len,SRC['reflections'].values()))==59 and all(x.get('solution') and x.get('prompt') for group in SRC['reflections'].values() for x in group))
check('13 mini blocks contain exactly 3 items',len(SRC['theory_mini'])==13 and all(len(x)==3 for x in SRC['theory_mini']))
check('9 flow blocks contain 7 semantic nodes',len(SRC['flow_blocks'])==9 and all(len(b)==7 for b in SRC['flow_blocks']))
check('All 13 TikZ SVG figures exist and parse',len(SRC['figures'])==13 and all((WEB/'assets/figures'/f'{f}.svg').exists() and ET.parse(WEB/'assets/figures'/f'{f}.svg') is not None for f in SRC['figures']))
check('All 9 flow SVG diagrams exist and parse',all((WEB/'assets/algorithms'/f'algorithm-{i:02}.svg').exists() and ET.parse(WEB/'assets/algorithms'/f'algorithm-{i:02}.svg') is not None for i in range(1,10)))
check('Local math rendering bundle present',(WEB/'vendor/mathjax-tex-svg-full.js').stat().st_size>1000000)
text='\n'.join(p.get_text() for p in fitz.open(PDF))
check('All 30 example IDs in source PDF',all(x['id'] in text for x in SRC['examples']))
check('All 90 practice IDs in source PDF',all(x['id'] in text for x in SRC['practice']))
check('All 59 reflection IDs in source PDF',all(x['id'] in text for v in SRC['reflections'].values() for x in v))
check('All sources mapped',len(SRC['sources'])==len(M['source_count'] if isinstance(M['source_count'],list) else SRC['sources']))
check('Main-plan progress key absent from book scripts','olympiad_math_plan_v2' not in (WEB/'app.js').read_text())
html=(WEB/'index.html').read_text();app=(WEB/'app.js').read_text();css=(WEB/'app.css').read_text();math=(WEB/'vendor/mathjax-tex-svg-full.js').read_text()
with sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
 page=browser.new_page(viewport={'width':1440,'height':900},device_scale_factor=1)
 page.on('pageerror',lambda e:ERRORS.append(str(e)))
 page.set_content(html,wait_until='domcontentloaded');page.add_style_tag(content=css);page.evaluate("Object.defineProperty(window,'localStorage',{configurable:true,value:{_data:{},setItem(k,v){this._data[k]=String(v)},getItem(k){return Object.prototype.hasOwnProperty.call(this._data,k)?this._data[k]:null},removeItem(k){delete this._data[k]}}})");page.add_script_tag(content=math);page.add_script_tag(content=app);page.wait_for_timeout(900)
 check('Loads book and introductory navigation',page.locator('.book-cover').count()==1 and page.locator('#table-of-contents a').count()==21)
 check('Book data embedded exactly',page.evaluate("JSON.stringify(window.__MB_TEST__.BOOK)===JSON.stringify(JSON.parse(document.getElementById('book-content').textContent))"))
 check('MathJax renders mathematical fragments',page.locator('mjx-container').count()>1)
 for width in [320,375,768,1024,1440]:
  page.set_viewport_size({'width':width,'height':880})
  page.evaluate("location.hash='#theory-03'");page.wait_for_timeout(350)
  overflow=page.evaluate('document.documentElement.scrollWidth>window.innerWidth')
  check(f'No overflow theory at {width}px',not overflow, {'scrollWidth':page.evaluate('document.documentElement.scrollWidth')})
  page.evaluate("location.hash='#practice'");page.wait_for_timeout(450)
  check(f'No overflow practice at {width}px',not page.evaluate('document.documentElement.scrollWidth>window.innerWidth'))
 page.set_viewport_size({'width':375,'height':812})
 page.locator('#menu-open').click();check('Mobile table of contents opens',page.locator('#sidebar').evaluate('(e)=>e.classList.contains("open")'))
 page.keyboard.press('Escape');check('Escape closes mobile menu',not page.locator('#sidebar').evaluate('(e)=>e.classList.contains("open")'))
 page.set_viewport_size({'width':1440,'height':900})
 page.evaluate("location.hash='#practice'");page.wait_for_timeout(450)
 check('10 problems per practice page',page.locator('.problem').count()==10)
 page.locator('[data-hint]').first.click();page.wait_for_timeout(150)
 check('Hint 1 appears, hint 2 withheld',page.locator('[data-hint-panel]').first.is_visible() and page.locator('[data-hint-panel]').first.locator('p').count()==1)
 page.locator('[data-hint]').first.click();page.wait_for_timeout(150)
 check('Hint 2 progressive reveal',page.locator('[data-hint-panel]').first.locator('p').count()==2)
 page.locator('[data-reveal]').first.click();check('Solution toggles visibility',page.locator('[data-solution-panel]').first.is_visible())
 page.locator('[data-note]').first.fill('Моё доказательство: 14−6=8.');
 page.locator('[data-status]').first.select_option('solved');
 check('Solved status updates 1/90',page.locator('#progress-count').inner_text()=='1 / 90')
 check('Independent progress namespace',page.evaluate("localStorage.getItem('mathblast_book_progress_v1:MB-W01-L1')!==null"))
 check('Source-plan key untouched',page.evaluate("localStorage.getItem('olympiad_math_plan_v2')===null"))
 page.reload() if False else None
 page.evaluate("location.hash='#answers'");page.wait_for_timeout(400)
 check('Answer table has 45 double rows',page.locator('.answer-table tbody tr').count()==45)
 page.locator('.answer-table tbody tr').first.locator('a').first.click();page.wait_for_timeout(400)
 check('Answer links land at matching ID',page.locator('.problem').first.get_attribute('id')==SRC['practice'][0]['id'])
 check('Student solution persisted',page.locator('[data-note]').first.input_value().startswith('Моё доказательство'))
 page.evaluate("location.hash='#solutions'");page.wait_for_timeout(500)
 check('10 full solutions per page',page.locator('article[id^="solution:"]').count()==10)
 page.evaluate("location.hash='#examples'");page.wait_for_timeout(700)
 check('All 30 examples rendered',page.locator('.example-card').count()==30)
 page.evaluate("location.hash='#methods'");page.wait_for_timeout(800)
 check('All 9 algorithms visible',page.locator('img.algorithm-img').count()==9)
 page.evaluate("location.hash='#sources'");page.wait_for_timeout(400)
 check('All 6 bibliography sources rendered',page.locator('.source').count()==6)
 page.evaluate("location.hash='#practice'");page.wait_for_timeout(300)
 page.locator('#theme-toggle').click();check('Dark theme toggles',page.locator('body').evaluate('(e)=>e.classList.contains("dark")'))
 raw=page.evaluate('window.__MB_TEST__.printFullHTML()')
 check('Print HTML includes 90 full solutions',raw.count('Решение ')>=90)
 check('Print HTML includes all 90 practice IDs',all(p['id'] in raw for p in SRC['practice']))
 check('Print HTML includes 59 reflection prompts',all(x['prompt'][:12] in raw or ('&' in x['prompt'][:12]) for g in SRC['reflections'].values() for x in g))
 check('Browser JS no uncaught errors',len(ERRORS)==0,ERRORS[:5])
 browser.close()
summary={'passed':sum(RESULTS.values()),'total':len(RESULTS),'failed':[k for k,v in RESULTS.items() if not v],'checks':RESULTS,'details':DETAILS,'browser_errors':ERRORS,'environment':'Chromium headless. Sandbox browser navigation blocked; HTML/CSS/JS loaded via set_content + add_script_tag, local images verified via SVG XML separately.'}
(ROOT/'qa/results.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('\nRESULT',summary['passed'],'/',summary['total'],'FAILED',summary['failed']);sys.exit(0 if summary['passed']==summary['total'] else 1)